python
def positiveTraysFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a:
        if x>0: out.append(x)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int positiveTraysFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)if(x>0)out.add(x);}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
